document.addEventListener("DOMContentLoaded",init);function varietyRowLabelText(listingType){if(listingType==="rental")return"Duration";if(listingType==="service")return"Service Name";return"Variety"}function varietyRowPlaceholderText(listingType){if(listingType==="rental")return"e.g. ½ day, per day, per week";if(listingType==="service")return"e.g. Car Wash start price";return"e.g. 500g, Large"}function varietiesSectionText(listingType){if(listingType==="rental")return"Rental Durations & Prices";if(listingType==="service")return"Services & Prices";return"Varieties & Prices"}function onListingTypeChange(){const type=document.getElementById("product-listing-type").value;fillCategoryOptions(type,document.getElementById("product-category").value);updateVarietyLabels()}function fillCategoryOptions(listingType,keepId){const select=document.getElementById("product-category");const previous=select.value;const list=activeCategories().filter(c=>c.id==="other"?keepId==="other":!listingType||c.types.indexOf(listingType)!==-1);select.innerHTML='<option value="" disabled'+(previous?"":" selected")+">Choose a category…</option>"+list.map(c=>{const label=c.id==="other"?c.label+" (please re-file)":c.label;return`<option value="${escapeHtml(c.id)}">${escapeHtml(label)}</option>`}).join("");if(previous&&list.some(c=>c.id===previous))select.value=previous}const PRODUCTS_PAGE_SIZE=20;let ownerProducts=[];let productsHasMore=false;let productsTotal=0;let selectedImageFile=null;let clearPhoto2=false;let variantRowSeq=0;async function init(){const owner=await Auth.guardOwnerAuth();if(!owner)return;document.getElementById("store-name-label").textContent=owner.storeName;document.getElementById("add-product-btn").addEventListener("click",()=>openForm(null));document.getElementById("cancel-product-btn").addEventListener("click",closeForm);document.getElementById("add-variant-btn").addEventListener("click",()=>{clearFieldErrors();addVariantRow()});document.getElementById("product-listing-type").addEventListener("change",onListingTypeChange);document.getElementById("product-form").addEventListener("submit",onSaveProduct);document.getElementById("product-form").addEventListener("input",onFieldEdited);document.getElementById("product-description").addEventListener("input",updateDescriptionCount);document.getElementById("product-form").addEventListener("change",onFieldEdited);document.getElementById("product-image-input").addEventListener("change",onImageFileChange);document.getElementById("remove-photo2-btn").addEventListener("click",onRemovePhoto2);document.getElementById("owner-product-list").addEventListener("click",onListClick);document.getElementById("products-load-more").addEventListener("click",onLoadMore);await loadProducts()}async function loadProducts(opts){const limit=opts&&opts.limit||ownerProducts.length||PRODUCTS_PAGE_SIZE;const statusEl=document.getElementById("products-status");const stopLoading=startLoadingMessage(statusEl);const res=await Api.post("listOwnerProducts",{token:Auth.getToken(),limit:limit});stopLoading();if(!res.ok){showLoadFailedMessage(statusEl);return}ownerProducts=res.products;productsHasMore=!!res.hasMore;productsTotal=res.total;statusEl.textContent=ownerProducts.length===0?"You have no products yet — add your first one above.":`${ownerProducts.length} of ${res.total} product(s) shown.`;document.getElementById("products-load-more").classList.toggle("hidden",!productsHasMore);renderList()}function onLoadMore(){loadProducts({limit:ownerProducts.length+PRODUCTS_PAGE_SIZE})}function renderList(){const listEl=document.getElementById("owner-product-list");listEl.innerHTML=ownerProducts.map(p=>{const media=p.imageUrl?`<img src="${escapeHtml(optimizedImageUrl(p.imageUrl,IMG_W.thumb))}" alt="" loading="lazy" decoding="async">`:`<div class="placeholder-swatch category-${escapeHtml(categoryIdOf(p.category))}" aria-hidden="true">${escapeHtml(initials(p.name))}</div>`;const activeVariants=p.variants.filter(v=>v.status==="active");const priceRange=activeVariants.length?activeVariants.map(v=>formatMoney(v.price)).join(" / "):"No varieties yet";return`\n        <div class="owner-product-row" data-product-id="${escapeHtml(p.productId)}">\n          ${media}\n          <div class="row-info">\n            <strong>${escapeHtml(p.name)}</strong>\n            <span class="status-badge status-${escapeHtml(p.status)}">${escapeHtml(p.status)}</span>\n            <div class="helper-text">${priceRange}</div>\n          </div>\n          <div class="row-actions">\n            <button type="button" class="btn btn-small" data-action="edit">Edit</button>\n            <button type="button" class="btn btn-small" data-action="duplicate">Duplicate</button>\n            <button type="button" class="btn btn-small btn-danger" data-action="archive">Archive</button>\n          </div>\n        </div>\n      `}).join("")}function onListClick(e){const row=e.target.closest(".owner-product-row");if(!row)return;const productId=row.dataset.productId;const product=ownerProducts.find(p=>p.productId===productId);if(e.target.closest('[data-action="edit"]')){openForm(product)}else if(e.target.closest('[data-action="duplicate"]')){openForm(product,{duplicate:true})}else if(e.target.closest('[data-action="archive"]')){onArchive(product)}}async function onArchive(product){if(!confirm(`Archive "${product.name}"? It will no longer be visible to customers.`))return;const res=await Api.post("deleteProduct",{token:Auth.getToken(),productId:product.productId});if(!res.ok){alert(res.error||"Could not archive this product.");return}await loadProducts()}function openForm(product,opts){const duplicate=!!(product&&opts&&opts.duplicate);const section=document.getElementById("product-form-section");const heading=document.getElementById("product-form-heading");section.classList.remove("hidden");selectedImageFile=null;clearPhoto2=false;document.getElementById("product-image-input").value="";document.getElementById("product-form-error").textContent="";clearFieldErrors();const preview=document.getElementById("image-preview");document.getElementById("variant-rows").innerHTML="";document.getElementById("duplicate-photo-note").hidden=!duplicate;if(product){heading.textContent=duplicate?`Duplicate: ${product.name}`:`Edit: ${product.name}`;document.getElementById("product-id").value=duplicate?"":product.productId;document.getElementById("product-name").value=duplicate?`${product.name} (copy)`:product.name;document.getElementById("product-description").value=product.description||"";const type=listingTypeOf(product);const existing=categoryIdOf(product.category);document.getElementById("product-listing-type").value=type;fillCategoryOptions(type,duplicate?"":existing);document.getElementById("product-category").value=existing;document.getElementById("product-status").value=product.status||"active";if(product.imageUrl&&!duplicate){preview.src=optimizedImageUrl(product.imageUrl,IMG_W.card);preview.classList.remove("hidden")}else{preview.classList.add("hidden")}showPhoto2(duplicate?"":product.imageUrl2);const activeVariants=product.variants.filter(v=>v.status==="active");if(activeVariants.length===0)addVariantRow();else activeVariants.forEach(v=>addVariantRow(duplicate?Object.assign({},v,{variantId:""}):v))}else{heading.textContent="Add Product";document.getElementById("product-id").value="";document.getElementById("product-name").value="";document.getElementById("product-description").value="";document.getElementById("product-listing-type").value="";fillCategoryOptions("","");document.getElementById("product-category").value="";document.getElementById("product-status").value="active";preview.classList.add("hidden");showPhoto2("");addVariantRow()}updateVarietyLabels();updateDescriptionCount();UnsavedGuard.watch(document.getElementById("product-form"),{skipWhenHidden:true});section.scrollIntoView({behavior:"smooth"})}function closeForm(){UnsavedGuard.release(document.getElementById("product-form"));document.getElementById("product-form-section").classList.add("hidden")}function addVariantRow(variant){variantRowSeq++;const rowId=`variant-row-${variantRowSeq}`;const wrapper=document.createElement("div");wrapper.className="variant-row";wrapper.dataset.variantId=variant?variant.variantId:"";const listingType=document.getElementById("product-listing-type").value;const rowLabel=varietyRowLabelText(listingType);const rowPlaceholder=varietyRowPlaceholderText(listingType);wrapper.innerHTML=`\n    <div class="field">\n      <label for="${rowId}-label" class="is-required">${escapeHtml(rowLabel)}</label>\n      <input id="${rowId}-label" class="variant-label" placeholder="${escapeAttr(rowPlaceholder)}" value="${escapeAttr(variant?variant.label:"")}" required>\n    </div>\n    <div class="field">\n      <label for="${rowId}-price" class="is-required">Price</label>\n      <input id="${rowId}-price" class="variant-price" type="number" min="0.01" step="0.01" value="${variant?variant.price:""}" required>\n    </div>\n    <div class="field">\n      <label for="${rowId}-stock">Stock (blank = unlimited)</label>\n      <input id="${rowId}-stock" class="variant-stock" type="number" min="0" step="1" placeholder="Unlimited" value="${variant&&variant.stockQty!==""&&variant.stockQty!=null?variant.stockQty:""}">\n    </div>\n    <button type="button" class="btn btn-small btn-danger remove-variant-btn">Remove</button>\n  `;wrapper.querySelector(".remove-variant-btn").addEventListener("click",()=>wrapper.remove());document.getElementById("variant-rows").appendChild(wrapper)}function updateVarietyLabels(){const listingType=document.getElementById("product-listing-type").value;document.getElementById("varieties-label").textContent=varietiesSectionText(listingType);const rowLabel=varietyRowLabelText(listingType);const rowPlaceholder=varietyRowPlaceholderText(listingType);document.querySelectorAll("#variant-rows .variant-row .variant-label").forEach(input=>{const label=input.closest(".field").querySelector("label");if(label)label.textContent=rowLabel;input.placeholder=rowPlaceholder})}function onImageFileChange(e){const file=e.target.files[0];if(!file)return;selectedImageFile=file;UnsavedGuard.markDirty(document.getElementById("product-form"));const preview=document.getElementById("image-preview");const reader=new FileReader;reader.onload=()=>{preview.src=reader.result;preview.classList.remove("hidden")};reader.readAsDataURL(file)}function showPhoto2(url){const field=document.getElementById("existing-photo2-field");const img=document.getElementById("image-preview-2");if(!field||!img)return;if(url){img.src=optimizedImageUrl(url,IMG_W.card);field.classList.remove("hidden")}else{field.classList.add("hidden")}}function onRemovePhoto2(){clearPhoto2=true;showPhoto2("");UnsavedGuard.markDirty(document.getElementById("product-form"))}function setSaveProductBusy(saveBtn,label){saveBtn.disabled=true;saveBtn.innerHTML=`${label}<span class="btn-saving-dots"><span></span><span></span><span></span></span>`}function setSaveProductIdle(saveBtn){saveBtn.disabled=false;saveBtn.textContent="Save Product"}const DESCRIPTION_MAX=2e3;const DESCRIPTION_WARN_AT=1800;const NAME_MAX=150;function updateDescriptionCount(){const n=document.getElementById("product-description").value.trim().length;const out=document.getElementById("description-count");out.hidden=n<DESCRIPTION_WARN_AT;out.classList.toggle("is-over",n>DESCRIPTION_MAX);out.textContent=n>DESCRIPTION_MAX?`${(n-DESCRIPTION_MAX).toLocaleString()} characters over the ${DESCRIPTION_MAX.toLocaleString()} limit - shorten it to save.`:`${(DESCRIPTION_MAX-n).toLocaleString()} characters left`}let fieldErrorSeq=0;function clearFieldErrors(){const form=document.getElementById("product-form");form.querySelectorAll(".field-error").forEach(el=>el.remove());form.querySelectorAll('[aria-invalid="true"]').forEach(el=>{el.removeAttribute("aria-invalid");el.removeAttribute("aria-describedby")})}function showFieldError(control,message,existingMsg){clearFieldErrors();let msg=existingMsg;if(!msg){msg=document.createElement("p");msg.className="field-error";msg.id=`field-error-${++fieldErrorSeq}`;msg.textContent=message;const row=control.closest(".variant-row");if(row)row.appendChild(msg);else control.insertAdjacentElement("afterend",msg)}if(/^(INPUT|SELECT|TEXTAREA)$/.test(control.tagName)){control.setAttribute("aria-invalid","true");control.setAttribute("aria-describedby",msg.id)}control.focus({preventScroll:true});control.scrollIntoView({block:"center",behavior:"smooth"})}function onFieldEdited(e){if(e.target.getAttribute&&e.target.getAttribute("aria-invalid")==="true")clearFieldErrors()}function validateProductForm(){const name=document.getElementById("product-name");if(!name.value.trim()){showFieldError(name,"Please enter a name for this listing.");return false}if(name.value.trim().length>NAME_MAX){showFieldError(name,`Keep the name to ${NAME_MAX} characters or fewer.`);return false}const description=document.getElementById("product-description");if(description.value.trim().length>DESCRIPTION_MAX){showFieldError(description,null,document.getElementById("description-count"));return false}const type=document.getElementById("product-listing-type");if(!type.value){showFieldError(type,"Please choose what you are offering.");return false}const category=document.getElementById("product-category");if(!category.value){showFieldError(category,"Please choose a category.");return false}const rows=Array.from(document.querySelectorAll("#variant-rows .variant-row"));if(rows.length===0){showFieldError(document.getElementById("add-variant-btn"),"Add at least one variety (e.g. a size or pack) with a price.");return false}const noun=varietyRowLabelText(type.value).toLowerCase();const variants=[];for(const row of rows){const labelInput=row.querySelector(".variant-label");const priceInput=row.querySelector(".variant-price");const stockInput=row.querySelector(".variant-stock");const label=labelInput.value.trim();const price=parseFloat(priceInput.value);const stockRaw=stockInput.value.trim();if(!label){showFieldError(labelInput,`Please fill in a ${noun}.`);return false}if(isNaN(price)||price<=0){showFieldError(priceInput,"Enter a price greater than zero.");return false}if(stockRaw!==""&&!/^\d+$/.test(stockRaw)){showFieldError(stockInput,"Leave blank for unlimited, or enter a whole number (0 or more).");return false}variants.push({variantId:row.dataset.variantId||undefined,label:label,price:price,stockQty:stockRaw===""?"":parseInt(stockRaw,10)})}return variants}async function onSaveProduct(e){e.preventDefault();const errorEl=document.getElementById("product-form-error");errorEl.textContent="";const variants=validateProductForm();if(!variants)return;const productId=document.getElementById("product-id").value||undefined;const payload={token:Auth.getToken(),productId:productId,name:document.getElementById("product-name").value.trim(),description:document.getElementById("product-description").value.trim(),category:document.getElementById("product-category").value,listingType:document.getElementById("product-listing-type").value,status:document.getElementById("product-status").value,variants:variants};if(clearPhoto2)payload.imageUrl2="";const saveBtn=document.getElementById("save-product-btn");setSaveProductBusy(saveBtn,productId?"Saving":"Adding");const action=productId?"updateProduct":"createProduct";const res=await Api.post(action,payload);if(!res.ok){errorEl.textContent=res.error||"Could not save this product.";setSaveProductIdle(saveBtn);return}document.getElementById("product-id").value=res.productId;const reloadOpts=productId?undefined:{limit:productsTotal+1};if(selectedImageFile){setSaveProductBusy(saveBtn,"Uploading photo 1");let uploadOk=false;try{const{base64:base64,mimeType:mimeType}=await compressImage(selectedImageFile);const uploadRes=await Api.post("uploadProductImage",{token:Auth.getToken(),productId:res.productId,imageBase64:base64,mimeType:mimeType,slot:1});uploadOk=uploadRes.ok;if(!uploadOk){errorEl.textContent=`Product saved, but photo 1 upload failed: ${uploadRes.error||"unknown error"}. Click Save Product to try the photo again.`}}catch(err){errorEl.textContent="Product saved, but photo 1 could not be processed. Click Save Product to try the photo again."}if(!uploadOk){setSaveProductIdle(saveBtn);await loadProducts(reloadOpts);return}}setSaveProductIdle(saveBtn);UnsavedGuard.markSaved(document.getElementById("product-form"));closeForm();await loadProducts(reloadOpts)}